function goalPanel(){const g=catalogGroups.find(x=>x.id===learningGoal.area);return `<section class="goal-panel"><div class="goal-intro"><span class="catalog-kicker">ZURE IKASKETA · ZURE AUKERA</span><h2>Nire helburua</h2><p>Aukeratu gaur landu nahi duzuna, presarik gabe.</p></div><div class="goal-controls"><fieldset><legend>Galdera kopurua</legend><div class="goal-choice">${[3,6,12].map(n=>`<button aria-pressed="${learningGoal.size===n}" class="${learningGoal.size===n?"selected":"alt"}" onclick="updateGoal('size',${n})">${n}</button>`).join("")}</div></fieldset><fieldset><legend>Ariketa mota</legend><div class="goal-choice">${[["choose","Aukeratu"],["write","Idatzi"]].map(([k,label])=>`<button aria-pressed="${learningGoal.mode===k}" class="${learningGoal.mode===k?"selected":"alt"}" onclick="updateGoal('mode','${k}')">${label}</button>`).join("")}</div></fieldset><div><label for="goal-area">Ikasgunea</label><select id="goal-area" onchange="updateGoal('area',this.value)">${[["all","Guztiak"],...catalogGroups.map(x=>[x.id,x.name])].map(([k,label])=>`<option value="${k}" ${learningGoal.area===k?"selected":""}>${esc(label)}</option>`).join("")}</select></div></div><div class="goal-footer"><small>${Math.min(learningGoal.size,goalPool().length)} galdera · ${esc(g?g.name:"Ikasgune guztiak")} · Fitxen praktika</small><button onclick="startGoal()">Nire saioa hasi ${homeIcon("arrow")}</button></div></section>`}
