function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){let k=Math.floor(Math.random()*(i+1));[a[i],a[k]]=[a[k],a[i]]}return a}
function declQuestions(){let a=[];for(let m of D.decl.models){for(let k of ["NOR","NORK","NORI","NON","NORA","NONDIK"]){let ds=m.fixed?["fixed"]:["sg","pl","ind"];for(let d of ds){let answer=form(m,k,d);if(answer&&m.forms[k]&&a.length<10000)a.push({id:"D09-"+m.lemma+"-"+k+"-"+d,family:"decl",prompt:m.lemma+" · "+k+" · "+dets[d],answer,wrong:[],why:"Jasotako ereduaren forma; ez da erabilera guztien epaia.",contrast:"Kasuaren galderari eta mugaketari erreparatu.",strict:false})}}}return a}
async function start(id,m){if(exam&&!exam.done)return;if(id==="unified"){const box=document.querySelector(".unified-practice");if(!box)return;const b=box.querySelector("button");if(b.disabled)return;b.disabled=true;const note=document.createElement("p");note.setAttribute("role","status");note.textContent="Aditzen galderak prestatzen…";box.append(note);try{await window.HitzBiraVerbs.prepareMixed();if(!box.isConnected||view!==2)return}catch(e){note.textContent=e.message||"Ezin izan dira adizkiak kargatu. Saiatu berriro.";b.disabled=false;return}}exam=null;sessionResults=[];mode=id==="unified"?"choose":m;let a=id==="unified"?[...shuffle(D.cards).slice(0,4),...(window.HitzBiraVerbs?.mixedItems(4)||[])]:id==="mixed"?D.mixed:id==="mixed-review"?D.mixed.filter(c=>isReviewItem(c.id)):id==="decl"?declQuestions():id==="decl-review"?declQuestions().filter(c=>isReviewItem(c.id)||pendingItem(h[c.id]||{})):D.cards.filter(c=>id==="all"||id===c.family||id===c.id||(id==="review"&&isReviewItem(c.id)));queue=shuffle(a);if(["all","mixed","decl"].includes(id))queue=queue.slice(0,12);if(id==="decl"||id==="decl-review")mode="write";if(id==="mixed-review")mode="identify";pos=0;score=0;view=2;next();scrollTo(0,0)}function next(){answerDraft="";selected=null;hint=false;choices=queue[pos]?shuffle([queue[pos].answer,...queue[pos].wrong]):[];draw()}function isReviewItem(id){return h[id]?.lastResult==="incorrect"}
function pendingItem(v){return v.lastResult==="unverified"||(!v.lastResult&&v.last===false)}
function pendingComparisons(){return Object.values(h).filter(pendingItem).length}
function pendingCardList(){const ids=Object.keys(h).filter(id=>pendingItem(h[id])&&C(id));return ids.length?'<div class="pending-list">'+ids.slice(0,8).map(id=>'<button class="alt" onclick="openCard('+j(id)+')">'+esc(C(id).title)+' · Fitxa ikusi</button>').join("")+'</div>'+(ids.length>8?'<small>'+ids.length+' fitxa guztira.</small>':""):""}
function record(s){if(!queue[pos]||selected!==null||!String(s).trim())return;let c=queue[pos],ok=match(c,s,mode),v=h[c.id]||{n:0,ok:0,auto:0,family:c.family};selected=s;if(c.verbItem){window.HitzBiraVerbs.recordMixed(c.id,ok,String(s).slice(0,2000));sessionResults.push({id:c.id,family:c.family,prompt:exercisePrompt(c),result:ok?"match":"incorrect",assisted:!!hint,mode});score+=ok?1:0;draw();return}v.n++;v.ok+=ok?1:0;v.auto+=ok&&!hint&&mode==="write"?1:0;v.lastResult=ok?"match":mode==="write"?"unverified":"incorrect";v.lastAssisted=!!hint;v.lastMode=mode;v.last=ok?true:mode==="write"?null:false;if(mode==="write"&&!ok)v.unverified=(v.unverified||0)+1;h[c.id]=v;sessionResults.push({id:c.id,family:c.family,prompt:exercisePrompt(c),result:v.lastResult,assisted:!!hint,mode});score+=ok?1:0;save({kind:"answer",item:c.id,answer:String(s).slice(0,2000),result:v.lastResult,assisted:!!hint,mode});draw()}

