let exam=null,examHistory=[],examSeen=[];
try{const saved=JSON.parse(localStorage.getItem(window.HBData.keyFor("hitzbira-assessment-v1"))||"{}");if(Array.isArray(saved.history))examHistory=saved.history;if(Array.isArray(saved.seen))examSeen=saved.seen}catch{}
function saveAssessment(){try{window.HBData.save("hitzbira-assessment-v1",{history:examHistory,seen:examSeen})}catch{}}
function assessmentAvailable(){return assessmentBank.filter(c=>!examSeen.includes(c.id))}
function assessmentIntro(){let n=assessmentAvailable().length;return `<section class="assessment-entry"><span class="focus-symbol cat-clause">${homeIcon("check")}</span><div><span class="catalog-kicker">EBALUATU · LAGUNTZARIK GABE</span><h2>Neure kabuz</h2><p>Galdera bereiziak, pistarik eta berehalako zuzenketarik gabe. Emaitza amaieran.</p><small>${n} galdera oraindik ikusi gabe gailu honetan. Proba orientagarria da; ez da maila ofiziala.</small></div><button onclick="startAssessment(${n===0})">${n?"Hasi proba":"Berriz egin (errepikapena)"} ${homeIcon("arrow")}</button></section>`}
function startAssessment(repeat=false){if(exam&&!exam.done)return;const pool=repeat?assessmentBank:assessmentAvailable();if(!pool.length)return;exam={runId:crypto.randomUUID(),items:shuffle(pool).slice(0,6).map(c=>({...c,options:shuffle([c.answer,...c.wrong])})),pos:0,answers:[],done:false,repeat:!!repeat};queue=[];view=2;detail="";draw();scrollTo(0,0)}
function exposeAssessment(){if(!exam||exam.done)return;const id=exam.items[exam.pos]?.id;if(id&&!examSeen.includes(id)){examSeen.push(id);saveAssessment()}}
function leaveAssessment(){if(!exam||exam.done){exam=null;draw();return}if(confirm("Proba utzi? Amaitu gabeko probaren puntuazioa ez da kalkulatuko; egindako erantzunak kontuko historian gordeko dira.")){exam=null;draw()}}
function assessPick(i){if(!exam||exam.done||exam.answers[exam.pos]!==undefined)return;let c=exam.items[exam.pos];if(!Number.isInteger(i)||i<0||i>=c.options.length)return;exam.answers[exam.pos]=c.options[i];window.HBData.activity({kind:"assessment_answer",item:c.id,runId:exam.runId,answer:c.options[i],match:c.answer===c.options[i]});if(exam.pos+1<exam.items.length){exam.pos++;draw();scrollTo(0,0);return}exam.done=true;let hits=exam.items.filter((x,k)=>x.answer===exam.answers[k]).length;examHistory.push({runId:exam.runId,date:new Date().toISOString(),n:exam.items.length,hits,repeat:exam.repeat,ids:exam.items.map(x=>x.id),outcomes:exam.items.map((x,k)=>({id:x.id,match:x.answer===exam.answers[k]}))});saveAssessment();draw();scrollTo(0,0)}
function assessmentView(){if(exam.done){let hits=exam.items.filter((c,i)=>c.answer===exam.answers[i]).length;return `<div class="learning-screen cat-clause assessment-screen"><section class="learning-hero"><div><span class="catalog-kicker">EBALUAZIO ORIENTAGARRIA</span><h1>Proba amaituta!</h1><p>${exam.repeat?"Errepikapeneko emaitza.":"Gailu honetan lehen aldiz ikusitako galderak."}</p><p><strong>${hits} / ${exam.items.length}</strong> eredurekin bat.</p></div><span class="learning-hero-icon illustrated">${islandArt("clause")}</span></section><section class="learn-step"><h2>Orain, berrikusi</h2><p>Erantzunak amaieran baino ez dira erakusten.</p>${exam.items.map((c,i)=>`<div class="assessment-review"><strong>${i+1}. ${esc(c.prompt)}</strong><p>Zure erantzuna: ${esc(exam.answers[i])}</p><p class="${c.answer===exam.answers[i]?"assessment-match":"assessment-diff"}">Eredua: ${esc(c.answer)}</p><small>${esc(c.why)}</small>${optionFeedback(c,exam.answers[i],"choose")}<button class="alt" onclick="catalogFamily(${j(c.family)})">Gaia ikasi</button></div>`).join("")}</section><button onclick="exam=null;go(3)">Nire bidea</button><button class="alt" onclick="exam=null;draw()">Praktikara itzuli</button></div>`}
 exposeAssessment();let c=exam.items[exam.pos];return `<div class="learning-screen session-screen cat-neutral assessment-screen"><div class="session-top"><button class="alt" onclick="leaveAssessment()">← Proba utzi</button><span>Neure kabuz</span><strong>${exam.pos+1} / ${exam.items.length}</strong></div><div class="session-track" role="progressbar" aria-label="Probako aurrerapena" aria-valuemin="0" aria-valuemax="${exam.items.length}" aria-valuenow="${exam.pos}"><div style="width:${100*exam.pos/exam.items.length}%"></div></div><section class="session-question"><span class="catalog-kicker">EBALUATU · AUKERATU</span><h1 class="hb-prompt-heading">${renderPrompt(c.prompt)}</h1><p>Hautatu erantzuna. Ez da zuzenketarik erakutsiko proba amaitu arte.</p>${c.options.map((x,i)=>`<button class="answer" onclick="assessPick(${i})"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(x)}</span></button>`).join("")}</section></div>`}
function assessmentProgress(){let first=examHistory.filter(x=>!x.repeat),repeats=examHistory.filter(x=>x.repeat);return `<section class="learn-step"><h2>Neure kabuz · probak</h2><p>Praktikako saiakeretatik aparte.</p><div class="assessment-stats"><div><strong>${first.length}</strong><small>Lehen aldiko probak</small></div><div><strong>${first.reduce((n,x)=>n+x.hits,0)} / ${first.reduce((n,x)=>n+x.n,0)}</strong><small>Ereduarekin bat</small></div><div><strong>${repeats.length}</strong><small>Errepikapenak</small></div></div><button onclick="exam=null;go(2)">Praktikara ${homeIcon("arrow")}</button></section>`}


