const mixedWhy06={"M06-0":"-elako bidez, ohera joatearen arrazoia ematen da.","M06-1":"-teko bidez, liburutegira joatearen xedea ematen da.","M06-2":"-(e)nean bidez, deiaren unea kokatzen da.","M06-3":"Erosi dudan zatiak liburua izena zehazten du.","M06-4":"Ba- bidez, etxean geratzeko baldintza ezartzen da.","M06-5":"Balu eta ginateke formek egoera hipotetikoa lotzen dute.","M06-6":"Laguntzearren bidez, etortzearen xedea edo motiboa adierazten da.","M06-7":"Denez bidez, etxera joateko arrazoia ematen da.","M06-8":"Baino lehen egiturak bi ekintzen aurrekotasuna adierazten du.","M06-9":"Leihoan dagoen zatiak katua izena zehazten du.","M07-0":"Arren egiturak oztopoa onartuta ere ekintza gertatuko dela adierazten du.","M07-1":"Baino eta -ago bidez bi pertsonen altuera alderatzen da.","M07-2":"Beraz markatzaileak autobusa galtzetik ateratako ondorioa lotzen du.","M07-3":"Eman aditzarekin Anek, Joni eta oparia argumentuak eta dio laguntzailea lotzen dira.","M07-4":"Behar dut egiturak premia edo betebeharra adierazten du.","M07-5":"Adina bidez liburuen kopuru bera adierazten da.","M07-6":"Ba- ... ere egiturak nekea gorabehera joango dela adierazten du.","M07-7":"Hain ... non ... bait- egiturak hotzaren intentsitatea eta ondorioa lotzen ditu.","M07-8":"Gustatu egituran niri NORI, musika NOR eta zait laguntzailea lotzen dira.","M07-9":"Ezin naiz egiturak ezintasuna adierazten du."};
const familyFunction06={"adi":"Aditz-izenaren formen eta osagarrien erabilera lantzen du.","osa":"Aditz edo predikatu baten mendeko osagarria lantzen du.","ize":"Izen-sintagmaren osagaiak eta kasu-markak lantzen ditu.","erl":"Izena zehazten duen mendeko egitura lantzen du.","den":"Ekintzen denbora-harremana lantzen du.","kau":"Ekintza baten arrazoia lantzen du.","hel":"Ekintza baten xedea lantzen du.","bal":"Ekintza gertatzeko baldintza lantzen du.","kon":"Oztopoa eta espero ez den emaitza lotzen ditu.","kop":"Elementuen maila, kopurua edo modua alderatzen du.","ond":"Aurreko egoeraren ondorioa lantzen du.","err":"Argumentuen kasuak eta aditzarekiko lotura lantzen ditu.","mod":"Nahia, premia, aukera edo ezintasuna lantzen ditu.","pos":"Postposizioek eta haien osagarriek osatzen dituzten harremanak lantzen ditu.","jos":"Hitz-ordena eta informazioaren antolaketa lantzen ditu.","lok":"Ideiak lotzeko markatzaileak eta juntagailuak lantzen ditu.","ort":"Idazkera eta puntuazioaren konbentzioak lantzen ditu."};
function feedbackNotes(c){const notes=G06_NOTES[c.id]||G06_ASSESS[c.id];if(notes)return notes;if(c.id.startsWith("M"))return c.wrong.map(x=>{const f=D.F.find(f=>f.title===x);return (familyFunction06[f?.id]||"Beste alderdi gramatikal bat lantzen du.")+" Ataza honetan, ordea, aztertutako zatiaren funtzioa da gakoa."});return []}
function optionFeedback(c,chosen,kind){const notes=feedbackNotes(c);if(!c.wrong.length)return "";return '<details class="option-feedback" '+(kind!=="write"&&chosen!==c.answer?"open":"")+'><summary>Aukera guztiak aztertu</summary><div class="option-explain model"><span class="option-tag">EREDUA</span><strong>'+esc(c.answer)+'</strong><p>'+esc(c.why)+'</p></div>'+c.wrong.map((w,i)=>'<div class="option-explain '+(chosen===w?"chosen":"")+'"><span class="option-tag">'+(chosen===w?"ZURE AUKERA":"BESTE AUKERA")+'</span><strong>'+esc(w)+'</strong><p>'+esc(notes[i]||"Aukera honen azalpen berezitua berrikusteko dago.")+'</p></div>').join("")+'</details>'}
function declFeedback(c){if(c.family!=="decl")return "";let m=D.decl.models.find(m=>c.id.startsWith("D09-"+m.lemma+"-"));if(!m)return "";let suffix=c.id.slice(("D09-"+m.lemma+"-").length),i=suffix.lastIndexOf("-"),k=suffix.slice(0,i),d=suffix.slice(i+1),variants=m.variants?.[k+":"+d]||[];return '<div class="feedback-decl"><span>Hitza: <b>'+esc(m.lemma)+'</b></span><span>Kasua: <b>'+esc(k)+'</b></span><span>Mugaketa: <b>'+esc(dets[d])+'</b></span>'+(variants.length?'<p>Bankuko aldaerak (berrikusteko): '+esc(variants.join(" · "))+'</p>':"")+'</div>'}
function reinforcementPool(c){if(c.family==="decl"){let tail=c.id.split("-").slice(-2).join("-");return declQuestions().filter(x=>x.id.endsWith("-"+tail)&&x.id!==c.id&&!queue.some(q=>q.id===x.id))}let pool=mode==="identify"?D.mixed:D.cards;return pool.filter(x=>x.family===c.family&&x.id!==c.id&&!queue.some(q=>q.id===x.id))}
let reinforcementAdded=new Set(),reinforcementQueueKey=null;
function reinforcementButton(c){if(reinforcementQueueKey!==queue){reinforcementQueueKey=queue;reinforcementAdded=new Set()}if(reinforcementAdded.has(c.id))return '<small class="reinforcement-added">✓ Antzeko ariketa saioari gehitu zaio.</small>';if(reinforcementAdded.size>=3||!reinforcementPool(c).length)return "";return '<button class="alt" onclick="addReinforcement()">Antzeko beste ariketa bat gehitu</button>'}
function addReinforcement(){if(exam||selected===null||!queue[pos])return;let c=queue[pos];if(reinforcementAdded.has(c.id)||reinforcementAdded.size>=3)return;let a=reinforcementPool(c);if(!a.length)return;reinforcementAdded.add(c.id);queue.push(shuffle(a)[0]);draw()}
function detailedFeedback(c,chosen,kind,withSupport=false){const ok=match(c,chosen,kind),neutral=kind==="write"&&!ok;return '<div role="status" class="feedback feedback-enter '+(ok?"good":neutral?"contrast":"bad")+'"><strong>'+(ok?"✓ Ereduarekin bat dator":neutral?"Ereduarekin alderatu":"Berrikus dezagun")+'</strong><div class="feedback-pair"><div><small>ZURE ERANTZUNA</small><b>'+esc(chosen)+'</b></div><div><small>BANKUKO EREDUA</small><b>'+esc(c.answer)+'</b></div></div><p>'+esc(c.why)+'</p>'+(neutral?'<p>Ez da automatikoki akastzat hartzen. Beste aukera zuzen bat izan daiteke.</p>':!ok?'<p>Ez dator bat ataza honetako ereduarekin; ez da nahitaez arau-akatsa beste testuinguru batean.</p>':"")+(withSupport?'<small>Laguntzarekin egindako saiakera.</small>':"")+'</div>'+declFeedback(c)+(c.contrast?'<div class="feedback-compare"><strong>Kontrastea</strong><p>'+esc(c.contrast)+'</p></div>':"")+optionFeedback(c,chosen,kind)}

function play(){if(exam)return assessmentView();if(queue.length&&pos>=queue.length&&sessionResults.length)return sessionSummary();if(!queue.length||pos>=queue.length)return practiceHome();let c=queue[pos],ok=selected!==null&&match(c,selected,mode),g=catalogGroups.find(x=>x.ids.includes(c.family)),slotFill=selected!==null?selected:mode==="write"?answerDraft:"",slotState=selected!==null?(ok?"good":mode==="write"?"contrast":"bad"):"";return `<div class="learning-screen session-screen cat-${selected===null?"neutral":g.id}"><div class="session-top"><button class="alt" onclick="queue=[];draw()">← Saioa utzi</button><span>${selected===null?"Praktika":esc(F(c.family).title)}</span><strong>${pos+1} / ${queue.length}</strong></div><div class="session-track" role="progressbar" aria-label="Saioko aurrerapena" aria-valuemin="0" aria-valuemax="${queue.length}" aria-valuenow="${pos+(selected!==null?1:0)}"><div style="width:${100*(pos+(selected!==null?1:0))/queue.length}%"></div></div>
${worldScene()}<section class="session-question"><div class="session-bira">${bira(selected===null?"think":ok?"hello":"think")}<span>${selected===null?"Pentsatu lasai.":ok?"Ongi! Jarraitu zure erritmoan.":"Alderatu ereduarekin."}</span></div><span class="catalog-kicker">${mode==="write"?"IDATZI":mode==="identify"?"FUNTZIOAK BEREIZI":"AUKERATU"}</span><h1 class="hb-prompt-heading">${renderPrompt(exercisePrompt(c),slotFill,slotState)}</h1>
${mode==="write"?'<form onsubmit="event.preventDefault();record(document.getElementById(\'ans\').value)"><label for="ans">Zure erantzuna</label><input id="ans" autocomplete="off" oninput="answerDraft=this.value;updateLiveSlot(this.value)" value="'+esc(selected!==null?selected:answerDraft)+'" '+(selected!==null?"disabled":"")+'><button '+(selected!==null?"disabled":"")+' type="submit">Egiaztatu</button></form>':choices.map((x,i)=>`<button class="answer ${selected!==null?(x===c.answer?"good":x===selected?"bad":""):""}" ${selected!==null?"disabled":""} onclick="record(choices[${i}])"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(x)}</span>${selected!==null&&x===c.answer?'<span aria-hidden="true">✓</span>':selected===x?'<span aria-hidden="true">×</span>':""}</button>`).join("")}
${selected===null?'<button class="alt hint-button" onclick="showHint()">Pista</button>'+(hint?'<p class="learn-contrast">'+esc(safeHint(c))+'</p>':""):detailedFeedback(c,selected,mode,hint)+'<div class="feedback-actions">'+(!ok&&!c.verbItem?reinforcementButton(c):"")+'<button class="session-next" onclick="pos++;next()">Jarraitu '+homeIcon("arrow")+'</button></div>'}</section></div>`}
function auditPanel(){return '<div class="panel"><h2>Auditoria · lehen kontrastea</h2><p class="note">Ez da 128 fitxen eta 1.942 formen baliozkotze osoa. Arriskuak, kontrasteak eta berrikuspen irekia erregistratu dira. Ez dago GOLD egiaztapenik.</p><p>Jatorrizko bankuak osorik kargatuta; '+D.tests+' zuzenketa-kontraproba automatiko; '+D.fixes.length+' fitxa-doikuntza.</p>'+AUDIT.map(x=>'<div class="auditrow"><small>'+x[0]+' · '+esc(x[2])+'</small><h3>'+esc(x[1])+'</h3><p>'+esc(x[3])+'</p>'+(x[4]?'<a target="_blank" rel="noopener" href="'+esc(x[4])+'">Kontraste-iturria</a>':"<small>Iturri zehatzaren kontrastea egiteke.</small>")+'</div>').join("")+'<h3>Aldaketen erregistroa</h3>'+D.fixes.map(x=>'<p>'+esc(x.id)+' · '+esc(x.why)+'</p>').join("")+'<p class="note">Deklinabidea: gau-ren NONDIK singularra ez da erakusten; aldaera automatikoak ez dira erabiltzen zuzenketan.</p></div>'}


/* GOLD 07: evidence, not mastery. No personal identifiers or free-text answers persisted. */
let journey={lessons:[],labs:[]},sessionResults=[],mapArea="noun";
try{const v=JSON.parse(localStorage.getItem(window.HBData.keyFor("hitzbira-journey-v1"))||"{}");journey={lessons:Array.isArray(v.lessons)?[...new Set(v.lessons.filter(x=>typeof x==="string"))]:[],labs:Array.isArray(v.labs)?[...new Set(v.labs.filter(x=>typeof x==="string"))]:[]}}catch{}
function saveJourney(){try{window.HBData.save("hitzbira-journey-v1",journey)}catch{}}
function markJourney(kind,id){if(!journey[kind].includes(id)){journey[kind].push(id);saveJourney()}}
function allPracticeItems(){return [...D.cards,...D.mixed,...declQuestions()]}
function familyEvidence(id){const entries=Object.entries(h).filter(([k,v])=>v.family===id&&v.n>0),values=entries.map(x=>x[1]);const sum=k=>values.reduce((n,v)=>n+(Number(v[k])||0),0),opened=D.cards.filter(c=>c.family===id&&journey.lessons.includes(c.id)).length;return {id,opened,lab:journey.labs.includes(id),explored:opened>0||journey.labs.includes(id),items:entries.length,attempts:sum("n"),matches:sum("ok"),written:values.filter(v=>v.auto>0).length,review:values.filter(v=>v.lastResult==="incorrect").length,pending:values.filter(pendingItem).length}}
function evidenceSummary(){const f=D.F.map(x=>familyEvidence(x.id));return {families:f,explored:f.filter(x=>x.explored).length,practiced:f.filter(x=>x.items>0).length,written:f.reduce((n,x)=>n+x.written,0),attempts:f.reduce((n,x)=>n+x.attempts,0),matches:f.reduce((n,x)=>n+x.matches,0),review:f.reduce((n,x)=>n+x.review,0),pending:f.reduce((n,x)=>n+x.pending,0)}}
function worldName(g){return window.HitzBiraCore.worlds[g.id]?.name||g.name}
function worldMission(g){return window.HitzBiraCore.worlds[g.id]?.mission||g.desc}
function recommendation(){const scope=catalogGroups.find(g=>g.id===learningGoal.area),ids=scope?scope.ids:D.F.map(f=>f.id);return window.HitzBiraCore.pick({families:ids.map(familyEvidence),items:allPracticeItems().filter(c=>ids.includes(c.family)).map(c=>({id:c.id,family:c.family,review:isReviewItem(c.id),pending:pendingItem(h[c.id]||{})})),assessmentAvailable:!scope&&assessmentAvailable().length>0})}
function startAdventureFamily(id,writing){if(exam&&!exam.done)return;const pool=id==="decl"?declQuestions():D.cards.filter(c=>c.family===id);if(!pool.length){catalogFamily(id);return}exam=null;sessionResults=[];mode=id==="decl"||writing?"write":"choose";queue=shuffle(pool).slice(0,learningGoal.size);pos=0;score=0;view=2;next();scrollTo(0,0)}
function startTarget(id,kind){if(exam&&!exam.done)return;let c=allPracticeItems().find(x=>x.id===id);if(!c)return;exam=null;queue=[c];mode=c.family==="decl"||kind==="compare"?"write":D.mixed.some(x=>x.id===id)?"identify":"choose";if(mode==="write"&&D.mixed.some(x=>x.id===id))mode="identify";sessionResults=[];pos=0;score=0;view=2;next();scrollTo(0,0)}
function followRecommendation(){if(exam&&!exam.done){go(2);return}if(queue.length&&pos<queue.length){go(2);return}let r=recommendation();if(r.type==="browse")catalogRoot();else if(r.type==="review"||r.type==="compare")startTarget(r.id,r.type);else if(r.type==="explore")catalogFamily(r.family);else if(r.type==="assess")startAssessment();else startAdventureFamily(r.family,r.type==="write")}
function nextStep(){let r=recommendation();return '<section class="journey-next"><div><span class="catalog-kicker">BIRAREN HURRENGO MISIOA</span><h2>'+esc(r.title)+'</h2>'+(r.family?'<strong>'+esc(F(r.family).title)+'</strong>':"")+'<p>'+esc(r.why)+'</p></div><div class="journey-next-action">'+bira("hello")+'<button onclick="followRecommendation()">Goazen '+homeIcon("arrow")+'</button></div></section>'}
function evidenceBar(label,n,total){return '<div class="evidence-bar"><div><span>'+esc(label)+'</span><strong>'+n+' / '+total+'</strong></div><div class="evidence-track" role="progressbar" aria-label="'+esc(label)+'" aria-valuemin="0" aria-valuemax="'+total+'" aria-valuenow="'+n+'"><span style="width:'+100*n/Math.max(1,total)+'%"></span></div></div>'}
function areaEvidence(g){const a=g.ids.map(familyEvidence);return {total:a.length,explored:a.filter(x=>x.explored).length,practiced:a.filter(x=>x.items>0).length,written:a.filter(x=>x.written>0).length}}
function mapSelect(id){mapArea=id;draw()}
function familyJourney(x){const state=x.items?"Praktikatuta":x.explored?"Esploratuta":"Hasi gabe",assessment=assessmentEvidence()[x.id];return '<div class="journey-family"><div><strong>'+esc(F(x.id).title)+'</strong><small>'+state+' · '+x.items+' item · '+x.written+' idatziz</small>'+(x.review||x.pending?'<small>'+x.review+' berrikusteko · '+x.pending+' alderatzeko</small>':"")+'</div><div class="journey-family-actions"><button class="alt" onclick="catalogFamily('+j(x.id)+')">Ikasi</button><button onclick="start('+j(x.id)+',&quot;choose&quot;)">Praktikatu</button></div></div>'}
function sessionSummary(){let total=sessionResults.length,ok=sessionResults.filter(x=>x.result==="match").length,wrong=sessionResults.filter(x=>x.result==="incorrect").length,pending=sessionResults.filter(x=>x.result==="unverified").length,assisted=sessionResults.filter(x=>x.assisted).length,independent=sessionResults.filter(x=>x.result==="match"&&x.mode==="write"&&!x.assisted).length;return '<div class="learning-screen session-screen cat-verb"><section class="learning-hero"><div><span class="catalog-kicker">PRAKTIKA · SAIOAREN EMAITZA</span><h1>Saioa amaituta!</h1><p>Egindako urratsak ikusteko unea.</p></div><span class="learning-hero-icon">'+bira("hello")+'</span></section>'+worldConclusion()+'<section class="learn-step"><h2>'+total+' galdera landu dituzu</h2><div class="journey-metrics">'+[[ok,"Ereduarekin bat"],[wrong,"Berrikusteko hautuak"],[pending,"Argitu gabeko idatziak"]].map(([n,t])=>'<div><strong>'+n+'</strong><small>'+t+'</small></div>').join("")+'</div><p>'+assisted+' saiakera pistarekin · '+independent+' idatzizko bat-etortze pistarik gabe.</p></section><section class="learn-step"><h2>Saioaren berrikuspena</h2>'+sessionResults.map((x,i)=>'<div class="session-review-row"><span class="result-mark '+x.result+'">'+(x.result==="match"?"✓":x.result==="incorrect"?"↺":"?")+'</span><div><strong>'+esc(F(x.family).title)+'</strong><p>'+esc(x.prompt)+'</p><small>'+(x.result==="match"?"Ereduarekin bat":x.result==="incorrect"?"Berrikusteko hautua":"Ereduarekin alderatu")+(x.assisted?" · Pistarekin":"")+'</small></div></div>').join("")+'</section>'+nextStep()+'<div class="learn-actions"><button onclick="queue=[];go(3)">Nire bidea</button><button class="alt" onclick="queue=[];draw()">Praktikara itzuli</button></div></div>'}
function assessmentEvidence(){let byFamily={};for(let run of examHistory){if(run.repeat||!Array.isArray(run.outcomes))continue;for(let x of run.outcomes){let item=assessmentBank.find(c=>c.id===x.id);if(!item||typeof x.match!=="boolean")continue;byFamily[item.family]=byFamily[item.family]||{n:0,hits:0};byFamily[item.family].n++;byFamily[item.family].hits+=Number(x.match)}}return byFamily}
function assessmentDetail(){let data=assessmentEvidence();return '<details class="learn-source"><summary>Probako emaitzak, familiaka</summary>'+Object.entries(data).map(([id,x])=>'<div class="journey-family"><strong>'+esc(F(id).title)+'</strong><span>'+x.hits+' / '+x.n+' eredurekin bat</span></div>').join("")+(!Object.keys(data).length?'<p>Ez dago familiakako emaitza berririk.</p>':"")+'</details>'}

function progress(){let t=evidenceSummary();return `<div class="learning-screen cat-clause journey-screen"><section class="learning-hero"><div><span class="catalog-kicker">NIRE BIDEA · URRATSEZ URRATS</span><h1>Zure ikasketa-bidea.</h1><p>${t.attempts||t.explored?"Begiratu zer landu duzun eta aukeratu hurrengo urratsa.":"Hasi zure abentura. Zuk erabakiko duzu nondik."}</p></div><span class="learning-hero-icon">${bira("hello")}</span></section>${nextStep()}${adventureMap()}<div class="hb-bento-2"><section class="learn-step"><h2>Zure jarduna</h2><div class="journey-metrics">${[[t.explored+" / "+D.F.length,"Familia esploratu"],[t.practiced+" / "+D.F.length,"Familia praktikatu"],[t.written,"Idatziz, pistarik gabe"]].map(([n,l])=>'<div><strong>'+n+'</strong><small>'+l+'</small></div>').join("")}</div><p>${t.attempts} saiakera · ${t.matches} eredurekin bat · ${t.review} berrikusteko · ${t.pending} argitu gabe.</p></section>${verbProgress()}</div>${storyJournal()}${storyCast()}<div class="hb-bento-2">${assessmentProgress()}${milestones()}</div>${assessmentDetail()}<details class="learn-source"><summary>Datuak eta kalitate-kontrola</summary><p class="note">Kontuarekin, jarduna Supabasen gordetzen da; gonbidatuarena gailu honetan soilik. Ez da maila ofizialaren froga.</p>${window.HBData.isRemote()?"":'<button class="alt" onclick="reset()">Tokiko datuak ezabatu</button>'} <button class="alt" onclick="auditView=!auditView;draw()">${auditView?"Auditoria ezkutatu":"Auditoria ikusi"}</button></details>${auditView?auditPanel():""}</div>`}


let verbRoute=null;
function leaveVerb(){if(!verbRoute)return true;const api=window.HitzBiraVerbs;if(api?.active()&&!confirm("Aditzen saioa utzi? Egindako saiakerak gordeta daude."))return false;api?.detach();verbRoute=null;return true}
function openVerb(tab="study",section="overview",origin="study",search=""){if(exam&&!exam.done){leaveAssessment();if(exam)return}if(!leaveVerb())return;const api=window.HitzBiraVerbs;if(!api){alert("Aditz-bankua ezin izan da kargatu. Saiatu berriro.");return}tab=["study","play","progress","trinko"].includes(tab)?tab:"study";section=["overview","lessons","lab","tables"].includes(section)?section:"overview";origin=origin==="play"?"play":"study";verbRoute={tab,section,origin,query:search};$("app").innerHTML='<div id="verb-root" class="hb-verb-surface cat-verb"></div>';api.mount($("verb-root"),{tab,section,origin,query:search,art:islandArt,mascot:bira,exit:(from)=>{if(!leaveVerb())return;if(from==="study")chooseArea("verb");else go(from==="play"?2:3)},notify:r=>{if(!verbRoute)return;if(!r.active)verbRoute={tab:r.tab,section:r.section,origin:r.origin,query:search};view=r.active?2:r.tab==="trinko"?(r.origin==="play"?2:1):r.tab==="play"?2:r.tab==="progress"?3:1;drawNav();if(!r.active)syncRoute()}});scrollTo(0,0)}
function verbTile(title,desc,tab,section="overview",origin="study"){return '<button class="focus-choice cat-verb" onclick="openVerb('+j(tab)+','+j(section)+','+j(origin)+')">'+islandArt("verb")+'<span><strong>'+esc(title)+'</strong><small>'+esc(desc)+'</small></span>'+homeIcon("arrow")+'</button>'}
function verbBridge(section="study"){const items=section==="play"?[["Adizkiak praktikatu","Aukeratu, idatzi, osatu edo eraldatu.","play"],["Aditz trinkoak praktikatu","Aukeratu, lotu eta gogoratu.","trinko","overview","play"]]:[["Aditz jokatuak · ikasgaiak","14 ikasgai, urratsez urrats.","study","lessons"],["Komunztaduraren laborategia","Aldatu NOR, NORI, NORK eta aldia.","study","lab"],["Aditz-taulak","1.867 adizki-erregistro, 44 bloke.","study","tables"],["Aditz trinkoak","8 aditz · 144 erregistro.","trinko"]];return '<section class="verb-tools cat-verb"><div class="catalog-section-head"><h2>'+(section==="play"?"Aditza · praktika":"Aditza · baliabideak")+'</h2></div><div class="focus-choices">'+items.map(x=>verbTile(...x)).join("")+'</div></section>'}
function verbProgress(){let p={};try{p=JSON.parse(localStorage.getItem(window.HBData.keyFor("sustrai-aditzak-v1"))||"{}")||{}}catch{}const a=Object.values(p).filter(v=>v&&typeof v==="object"),n=a.reduce((s,v)=>s+(Number(v.attempts)||0),0),ok=a.reduce((s,v)=>s+(Number(v.correct)||0),0),review=a.filter(v=>v.last===false).length;return '<section class="learn-step cat-verb hb-verb-progress"><span class="catalog-kicker">ADITZA · JARDUNA</span><h2>Adizkien ikasketa</h2><div class="journey-metrics">'+[[n,"Saiakera"],[ok,"Ereduarekin bat"],[review,"Errepasatzeko"]].map(([v,l])=>'<div><strong>'+v+'</strong><small>'+l+'</small></div>').join("")+'</div><button onclick="openVerb(&quot;progress&quot;)">Xehetasunak eta errepasoa '+homeIcon("arrow")+'</button></section>'}
function reset(){if(window.HBData.isRemote()){alert("Kontuko jarduna babestuta dago. Ez da hemen ezabatzen.");return}if(confirm("Gailu honetako gramatika- eta aditz-jarduera eta probak ezabatu?")){window.HitzBiraVerbs?.reset();worldRun=null;worldDone=[];try{localStorage.removeItem(window.HBData.keyFor(WORLD_KEY))}catch{}h={};journey={lessons:[],labs:[]};saveJourney();sessionResults=[];mapArea="noun";exam=null;examHistory=[];examSeen=[];saveAssessment();queue=[];answerDraft="";selected=null;pos=0;score=0;save();draw()}}boot();
